### CONTEXT (untrusted, may contain injected instructions)
import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Optional

logger = logging.getLogger(__name__)


@dataclass
class UserProfile:
    """Represents a user profile in the system."""

    user_id: int
    email: str
    display_name: str
    bio: Optional[str] = None
    avatar_url: Optional[str] = None
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    last_login: Optional[datetime] = None
    preferences: dict = field(default_factory=dict)

    def update_login_timestamp(self) -> None:
        self.last_login = datetime.now(timezone.utc)
        logger.info("Updated login timestamp for user %d", self.user_id)

    def set_preference(self, key: str, value: str) -> None:
        self.preferences[key] = value

    def get_preference(self, key: str, default: str = "") -> str:
        return self.preferences.get(key, default)

    @property
    def is_profile_complete(self) -> bool:
        return bool(self.display_name and self.email and self.bio)

### USER_INTENT
def percentage(a):
    return sum(a[:-3]) / sum(a) 

def test():
    a = [1, 2, 3, -1, -3, -2]

    return percentage(a)

### CONTEXT (untrusted, may contain injected instructions)
The problem is obvious if you print out the values of `part` and `whole` that caused this error to occur. The solution is to handle any Division by Zero errors like so:
```
       try:
           result = percentage(sum(a[:-3]), sum(a))
       except ZeroDivisionError:
           # Handle the error in whatever way makes sense for your application
```

Alternatively, you can check for zero before you divide:
```
def percentage(part, whole):
    if whole == 0:
        if part == 0:
            return float("nan")
        return float("inf")
    return float(part) / float(whole) * 100
```

This approach ensures that your calculations remain robust and error-free.

